CREATE TABLE IF NOT EXISTS public.vice_estate_events (seq bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, allocation_id uuid NOT NULL REFERENCES public.vice_estate_allocations(id) ON DELETE RESTRICT, event_type text NOT NULL, program text NOT NULL CHECK(program IN ('VICE','V4X')), units numeric(20,0) NOT NULL CHECK(units>0), actor_id uuid REFERENCES auth.users(id), correlation_id uuid NOT NULL UNIQUE, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE public.vice_estate_events ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.vice_estate_events FROM PUBLIC,anon,authenticated;
